class UsersController {
  usersService;
  constructor() {
    this.usersService = new UsersService;
  }
  getRoutes() {
    return new Elysia({
      prefix: "/users"
    }).get("/", async () => {
      try {
        return await this.usersService.getUsers();
      } catch (e) {
        logError(e, "getting users");
        throw e;
      }
    }).post("/", async ({ body }) => {
      try {
        const res = await this.usersService.postUser(body);
        return res;
      } catch (e) {
        logError(e, "creating user");
        throw e;
      }
    }, {
      body: usersPostValidator
    }).use(requireSelfMiddleware).get("/:id", async ({ params }) => {
      try {
        if (!params.id) {
          throw new MyError("id is required", 400 /* BAD_REQUEST */);
        }
        return await this.usersService.getUserById(Number(params.id));
      } catch (e) {
        logError(e, "getting user by id");
        throw e;
      }
    }, {
      params: idValidator
    }).patch("/:id", async ({ body, params }) => {
      try {
        if (!params.id) {
          throw new MyError("id is required", 400 /* BAD_REQUEST */);
        }
        const res = await this.usersService.patchUser(params.id, body);
        return res;
      } catch (e) {
        logError(e, "updating user");
        throw e;
      }
    }, {
      body: usersUpdateValidator,
      params: idValidator
    }).patch("/:id/password", async ({ body, params }) => {
      try {
        if (!params.id) {
          throw new MyError("id is required", 400 /* BAD_REQUEST */);
        }
        const res = await this.usersService.updatePassword(Number(params.id), body);
        return res;
      } catch (e) {
        logError(e, "updating user password");
        throw e;
      }
    }, {
      body: t.Object({
        password: passwordValidator()
      }),
      params: idValidator
    }).delete("/:id", async ({ params }) => {
      try {
        if (!params.id) {
          throw new MyError("id is required", 400 /* BAD_REQUEST */);
        }
        const res = await this.usersService.deleteUser(Number(params.id));
        return res;
      } catch (e) {
        logError(e, "deleting user");
        throw e;
      }
    }, {
      params: idValidator
    });
  }
}

// src/modules/refresh/refresh.schema.ts
var refreshTokens = pgTable("refresh_tokens", {
  id: uuid("id").primaryKey(),
  userId: integer("user_id").notNull().references(() => users.id, {
    onDelete: "cascade"
  }),
  tokenHash: text("token_hash").notNull(),
  expiresAt: timestamp("expires_at").notNull(),
  revokedAt: timestamp("revoked_at"),
  replacedBy: uuid("replaced_by"),
  createdAt: timestamp("created_at").defaultNow().notNull()
}, (table) => ({
  userIdIdx: index("refresh_tokens_user_id_idx").on(table.userId)
}));

// src/modules/refresh/refresh.repository.ts
class RefreshTokenRepository {
  async create(data) {
    const [token] = await db.insert(refreshTokens).values(data).returning();
    return token;
  }
  async findById(id) {
    const [token] = await db.select().from(refreshTokens).where(eq(refreshTokens.id, id)).limit(1);
    return token;
  }
  async findValidToken(id) {
    const [token] = await db.select().from(refreshTokens).where(and(eq(refreshTokens.id, id), isNull(refreshTokens.revokedAt))).limit(1);
    return token;
  }
  async revoke(id, replacedBy) {
    const [token] = await db.update(refreshTokens).set({
      revokedAt: new Date,
      replacedBy: replacedBy ?? null
    }).where(eq(refreshTokens.id, id)).returning();
    return token;
  }
  async revokeAllForUser(userId) {
    return db.update(refreshTokens).set({
      revokedAt: new Date
    }).where(and(eq(refreshTokens.userId, userId), isNull(refreshTokens.revokedAt)));
  }
  async delete(id) {
    return db.delete(refreshTokens).where(eq(refreshTokens.id, id));
  }
}

// src/modules/auth/auth.service.ts
class AuthService {
  userService;
  refreshTokenRepository;
  constructor() {
    this.userService = new UsersService;
    this.refreshTokenRepository = new RefreshTokenRepository;
  }
  issueTokenPair = async (user, role) => {
    const accessToken = signAccessToken({ userId: user.id, email: user.email, role });
    const id = newRefreshTokenId();
    const secret = generateRefreshTokenSecret();
    const tokenHash = await hashRefreshTokenSecret(secret);
    await this.refreshTokenRepository.create({
      id,
      userId: user.id,
      tokenHash,
      expiresAt: refreshTokenExpiry()
    });
    return { accessToken, refreshToken: encodeRefreshToken(id, secret) };
  };
  signup = async (user) => {
    const res = await this.userService.postUser(user);
    if (!res)
      throw new MyError("cannot signup", 304 /* NOT_MODIFIED */);
    const { accessToken, refreshToken } = await this.issueTokenPair(res, "user" /* USER */);
    return { user: res, accessToken, refreshToken };
  };
  emailSignin = async (user) => {
    const res = await this.userService.getUserByEmailUnsafe(user.email);
    if (!res)
      throw new MyError("user not found", 404 /* NOT_FOUND */);
    if (!res.isActive) {
      throw new MyError("user account is inactive", 401 /* UNAUTHORIZED */);
    }
    const matched = await comparePassword(user.password, res.password);
    if (!matched) {
      throw new MyError("invalid credential", 401 /* UNAUTHORIZED */);
    }
    const { password: _2, ...safeUser } = res;
    const { accessToken, refreshToken } = await this.issueTokenPair(safeUser, user.role ?? "user" /* USER */);
    return { user: safeUser, accessToken, refreshToken };
  };
  mobileSignin = async (user) => {
    const res = await this.userService.getUserByPhoneUnsafe(user.dialCode, user.mobile);
    if (!res)
      throw new MyError("user not found", 404 /* NOT_FOUND */);
    if (!res.isActive) {
      throw new MyError("user account is inactive", 401 /* UNAUTHORIZED */);
    }
    const matched = await comparePassword(user.password, res.password);
    if (!matched) {
      throw new MyError("invalid credential", 401 /* UNAUTHORIZED */);
    }
    if (user.role && user.role != res.role) {
      throw new MyError("invalid credential", 400 /* BAD_REQUEST */);
    }
    const { password: _2, ...safeUser } = res;
    const { accessToken, refreshToken } = await this.issueTokenPair(safeUser, user.role ?? "user" /* USER */);
    return { user: safeUser, accessToken, refreshToken };
  };
  refresh = async ({ refreshToken }) => {
    const decoded = decodeRefreshToken(refreshToken);
    if (!decoded)
      throw new MyError("invalid refresh token", 401 /* UNAUTHORIZED */);
    const existing = await this.refreshTokenRepository.findById(decoded.id);
    if (!existing)
      throw new MyError("invalid refresh token", 401 /* UNAUTHORIZED */);
    const secretMatches = await compareRefreshTokenSecret(decoded.secret, existing.tokenHash);
    if (!secretMatches) {
      throw new MyError("invalid refresh token", 401 /* UNAUTHORIZED */);
    }
    if (existing.revokedAt) {
      await this.refreshTokenRepository.revokeAllForUser(existing.userId);
      throw new MyError("refresh token reuse detected", 401 /* UNAUTHORIZED */);
    }
    if (existing.expiresAt.getTime() < Date.now()) {
      throw new MyError("refresh token expired", 401 /* UNAUTHORIZED */);
    }
    const user = await this.userService.getUserById(existing.userId);
    if (!user)
      throw new MyError("user not found", 404 /* NOT_FOUND */);
    if (!user.isActive) {
      throw new MyError("user account is inactive", 401 /* UNAUTHORIZED */);
    }
    const newId = newRefreshTokenId();
    const newSecret = generateRefreshTokenSecret();
    await this.refreshTokenRepository.create({
      id: newId,
      userId: existing.userId,
      tokenHash: await hashRefreshTokenSecret(newSecret),
      expiresAt: refreshTokenExpiry()
    });
    await this.refreshTokenRepository.revoke(existing.id, newId);
    const accessToken = signAccessToken({ userId: user.id, email: user.email, role: user.role ?? "user" /* USER */ });
    return { accessToken, refreshToken: encodeRefreshToken(newId, newSecret) };
  };
  logout = async ({ refreshToken }) => {
    const decoded = decodeRefreshToken(refreshToken);
    if (!decoded)
      throw new MyError("invalid refresh token", 401 /* UNAUTHORIZED */);
    const existing = await this.refreshTokenRepository.findById(decoded.id);
    if (existing && !existing.revokedAt) {
      const secretMatches = await compareRefreshTokenSecret(decoded.secret, existing.tokenHash);
      if (secretMatches) {
        await this.refreshTokenRepository.revoke(existing.id);
      }
    }
    return { success: true };
  };
  logoutAll = async (userId) => {
    await this.refreshTokenRepository.revokeAllForUser(userId);
    return { success: true };
  };
  me = async (userId) => {
    const user = await this.userService.getUserById(userId);
    if (!user)
      throw new MyError("user not found", 404 /* NOT_FOUND */);
    if (!user.isActive) {
      throw new MyError("user account is inactive", 401 /* UNAUTHORIZED */);
    }
    return user;
  };
}

