// node_modules/drizzle-orm/migrator.js
import crypto3 from "crypto";
import fs2 from "fs";
function readMigrationFiles(config) {
  const migrationFolderTo = config.migrationsFolder;
  const migrationQueries = [];
  const journalPath = `${migrationFolderTo}/meta/_journal.json`;
  if (!fs2.existsSync(journalPath)) {
    throw new Error(`Can't find meta/_journal.json file`);
  }
  const journalAsString = fs2.readFileSync(`${migrationFolderTo}/meta/_journal.json`).toString();
  const journal = JSON.parse(journalAsString);
  for (const journalEntry of journal.entries) {
    const migrationPath = `${migrationFolderTo}/${journalEntry.tag}.sql`;
    try {
      const query = fs2.readFileSync(`${migrationFolderTo}/${journalEntry.tag}.sql`).toString();
      const result2 = query.split("--> statement-breakpoint").map((it) => {
        return it;
      });
      migrationQueries.push({
        sql: result2,
        bps: journalEntry.breakpoints,
        folderMillis: journalEntry.when,
        hash: crypto3.createHash("sha256").update(query).digest("hex")
      });
    } catch {
      throw new Error(`No file ${migrationPath} found in ${migrationFolderTo} folder`);
    }
  }
  return migrationQueries;
}

// node_modules/drizzle-orm/node-postgres/migrator.js
async function migrate(db2, config) {
  const migrations = readMigrationFiles(config);
  await db2.dialect.migrate(migrations, db2.session, config);
}

// src/db/migrate.ts
var migrationsFolder = "./drizzle/migrations";
async function runMigrations() {
  if (!existsSync2(migrationsFolder)) {
    info("\u26A0\uFE0F Migrations folder does not exist. Skipping migration.");
    return;
  }
  const files = readdirSync(migrationsFolder).filter((f) => f.endsWith(".sql"));
  if (files.length === 0) {
    info("\u26A0\uFE0F No migration files found. Skipping migration.");
    return;
  }
  info(`\uD83D\uDE80 Running ${files.length} migration(s)...`);
  await migrate(db, { migrationsFolder });
  info("\u2705 Migrations completed successfully.");
}
async function main() {
  await runMigrations();
  return;
}
main().catch((err2) => {
  logError(err2, "Migrations");
  process.exit(1);
});

